def solve(data):
    packages = data['packages']
    roots = data['roots']
    names = sorted(packages)
    best_vector = None
    best_versions = None

    # Each constraint is an inclusive (minimum, maximum) version interval.
    initial_constraints = {
        name: [(bounds[0], bounds[1])] for name, bounds in roots.items()
    }

    def satisfies(version, constraints):
        return all(low <= version <= high for low, high in constraints)

    def rows_for(name, constraints):
        return sorted(
            (row for row in packages.get(name, [])
             if satisfies(row['version'], constraints)),
            key=lambda row: row['version'],
            reverse=True,
        )

    def search(selected, constraints):
        nonlocal best_vector, best_versions

        # Newly discovered dependencies may constrain packages already chosen.
        for name, row in selected.items():
            if not satisfies(row['version'], constraints.get(name, [])):
                return

        pending = set(constraints) - set(selected)
        if not pending:
            vector = version_vector(names, selected)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {
                    name: row['version'] for name, row in selected.items()
                }
            return

        # Optimistically allow every not-yet-selected package its best possible
        # version, even if it has not yet been reached by the dependency graph.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in selected:
                    upper.append(selected[name]['version'])
                elif name in constraints:
                    options = rows_for(name, constraints[name])
                    upper.append(max((row['version'] for row in options), default=-1))
                else:
                    available = [row['version'] for row in packages.get(name, [])]
                    upper.append(max([-1] + available))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        for row in rows_for(name, constraints[name]):
            next_selected = dict(selected)
            next_selected[name] = row
            next_constraints = {key: list(value) for key, value in constraints.items()}

            for dep in row['deps']:
                dep_name = dep['name']
                interval = (dep['min'], dep['max'])
                next_constraints.setdefault(dep_name, []).append(interval)

            search(next_selected, next_constraints)

    search({}, initial_constraints)
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
